const meta = {
  title: "Blocks/Form Block/Form",
  component: Form,
  decorators: [withBlockWrapper],
  args: { onSubmit: fn() },
  render: (args) => (
    <Form
      {...args}
      onSubmit={(fields) => {
        const fieldsAsStrings: Array<string> = [];
        fields.forEach((field) => fieldsAsStrings.push(field.value ?? "-"));

        const handler = action("submit");
        handler(fieldsAsStrings);
      }}
    />
  ),
} satisfies Meta<typeof Form>;

export default meta;

type Story = StoryObj<typeof meta>;

