/**
 * We previously had a bug where the month navigation was not working for forms
 * This test is to ensure that the navigation is always working as expected
 */
export const CalendarNavigation: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    //Wait for 1 second
    await new Promise((resolve) => setTimeout(resolve, 1000));

    //Expect to see the current month in the calendar
    const augustElement = canvas.getByText("Augusti");
    await expect(augustElement).toBeInTheDocument();

    //Click the navigation for next month
    await userEvent.click(canvas.getByLabelText("Nästa månad"));

    //Wait for 1 second
    await new Promise((resolve) => setTimeout(resolve, 1000));

    //Expect to see the next month in the calendar
    const septemberElement = canvas.getByText("September");
    await expect(septemberElement).toBeInTheDocument();
  },
  args: {
    ...Primary.args,
    formElements: [
      {
        type: "singleDateSelection",
        internalTitle: "date-field",
        label: "Which date you want?",
        emailLabel: "Selected Date",
        calendarDates: {
          startDate: "2023-08-28",
          endDate: "2023-08-31",
          selectedDates: [
            //One date for the next month
            {
              date: "2023-09-01T00:00:00.000Z",
              fullDate: "2023-09-01",
            },
          ],
        },
      },
    ],
  },
};
